// Sub-Workflow: Competitor Marketplace Live Price Scraper
const inputData = $input.first().json;
const sku = inputData.sku || inputData.query || 'UNKNOWN_SKU';
const asin = inputData.asin || 'B09DEFAULT';

// Real-world simulated competitor marketplace prices based on SKU
let result = {
  merchant: "Apex Retail",
  listed_price: 68.99,
  shipping_cost: 0.00,
  stock_status: "IN_STOCK",
  asin: asin,
  sku: sku,
  currency: "USD",
  scraped_at: new Date().toISOString()
};

if (sku === 'TECH-CAM-PREDATORY' || sku.includes('PREDATORY')) {
  result.merchant = "BargainHunter Direct";
  result.listed_price = 55.00;
  result.shipping_cost = 0.00;
  result.stock_status = "IN_STOCK";
} else if (sku === 'TECH-MIC-USB-02') {
  result.merchant = "AudioPro Marketplace";
  result.listed_price = 54.50;
  result.shipping_cost = 4.99;
  result.stock_status = "IN_STOCK";
}

return [{ json: result }];
